"""November 15 issue reproduction: actual UI, existing identities and no external writes."""
import importlib.util,unittest,json,os
from pathlib import Path
s=importlib.util.spec_from_file_location('existing',Path(__file__).with_name('qa-consolidated.py'));base=importlib.util.module_from_spec(s);s.loader.exec_module(base)
OUT=Path(os.environ.get('ARENA_NOV15_OUT','docs/qa-20261115/after'));OUT.mkdir(parents=True,exist_ok=True)
class Nov15(base.Consolidated):
 def shot(self,name):
  self.page.wait_for_function('()=>!document.querySelector("#toast")?.textContent');self.page.evaluate('scrollTo(0,0)');self.page.screenshot(path=str(OUT/(base.base.ENGINE+'-'+name+'.png')),full_page=True)
 def test_nov15_weekdays_edit_reload_and_family_projection(self):
  athlete=self.basic();self.nav('Schedule');p=self.page;p.get_by_role('button',name='Add Recurring Practice',exact=True).click();self.assertFalse(p.locator('#plan-end').is_visible());p.locator('#plan-title').fill('Monday Wednesday practice');p.locator('#plan-start').fill('2026-11-16');p.locator('#plan-until').fill('2026-11-30');p.locator('[name=plan-days][value="1"]').check();p.locator('[name=plan-days][value="3"]').check();p.locator('#plan-note').fill('Family-entered practice location');self.shot('weekly-form');p.get_by_role('button',name='Add to schedule',exact=True).click();p.wait_for_selector('#schedule-list article');self.assertEqual(p.locator('#schedule-list article').count(),5);plan=self.state()['profiles'][0]['plans'][0];self.assertEqual(plan['start'],plan['end']);self.assertEqual(plan['days'],[1,3]);sid=plan['id']
  views=p.get_by_role('navigation',name='Athlete schedule views',exact=True);views.get_by_role('button',name='Week',exact=True).click();counts=p.locator('.ap-week-day').evaluate_all('(xs)=>xs.map(x=>x.querySelectorAll("article").length)');self.assertEqual(counts,[1,0,1,0,0,0,0]);self.shot('weekly-calendar');views.get_by_role('button',name='List',exact=True).click();p.get_by_role('button',name='Edit series',exact=True).first.click();self.assertFalse(p.locator('#plan-end').is_visible());p.locator('#plan-note').fill('Updated family location');p.get_by_role('button',name='Save event / series',exact=True).click();p.wait_for_function('()=>JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0].plans[0].note==="Updated family location"');p.reload();p.wait_for_selector('#profile-nav');self.nav('Schedule');p.wait_for_selector('#schedule-list article');self.assertEqual(p.locator('#schedule-list article').count(),5);self.assertEqual(self.state()['profiles'][0]['plans'][0]['id'],sid);self.assertEqual(len(self.state()['profiles'][0]['plans']),1)
  with p.expect_download() as download:p.locator('#export-calendar').click()
  ics=Path(download.value.path()).read_text();self.assertEqual(ics.count('BEGIN:VEVENT'),5)
  events=p.evaluate('async()=>{const{athleteEvents}=await import("/assets/meet-sessions.js");return athleteEvents(JSON.parse(localStorage.getItem("arenaPathway.v2")).profiles[0],{opportunities:[]}).map(e=>({ref:e.occurrenceId,start:e.start,end:e.end}))}');self.assertEqual(len(set(e['ref'] for e in events)),5);self.assertTrue(all(e['start']==e['end'] for e in events));p.goto(base.base.BASE+'/my-ap?scenario=local&section=calendar');p.wait_for_selector('#platform-calendar');p.get_by_label('Calendar date',exact=True).fill('2026-11-16');p.get_by_label('Calendar date',exact=True).press('Tab');p.get_by_role('button',name='Week',exact=True).click();p.wait_for_selector('#platform-calendar .ap-activity');self.assertEqual(p.locator('#platform-calendar .ap-activity').count(),2);self.assertNotIn('Rivera',p.locator('#platform-calendar').inner_text());self.shot('family-calendar');(OUT/(base.base.ENGINE+'-recurrence.json')).write_text(json.dumps({'athleteId':athlete,'planId':sid,'events':events,'weekCounts':counts},indent=2)+'\n')
 def test_nov15_historical_span_is_only_corrected_after_explicit_edit(self):
  self.basic();p=self.page;p.evaluate("""()=>{const s=JSON.parse(localStorage.getItem('arenaPathway.v2'));s.profiles[0].plans=[{id:'historical-kept',name:'Older multi-day practice',kind:'practice',start:'2026-11-16',end:'2026-11-30',repeat:'weekly',until:'2026-11-30',days:[1,3],excludedDates:['2026-11-23'],overrides:{'2026-11-18':{name:'Retained exception',start:'2026-11-19',end:'2026-11-19'}}}];localStorage.setItem('arenaPathway.v2',JSON.stringify(s));}""");p.reload();p.wait_for_selector('#show-tryouts');self.nav('Schedule');self.assertEqual(self.state()['profiles'][0]['plans'][0]['end'],'2026-11-30');p.get_by_role('button',name='Edit series',exact=True).first.click();self.assertTrue(p.locator('#plan-multiple-days').is_checked());p.locator('#plan-multiple-days').uncheck();self.assertFalse(p.locator('#plan-end').is_visible());p.get_by_role('button',name='Save event / series',exact=True).click();p.wait_for_function("()=>JSON.parse(localStorage.getItem('arenaPathway.v2')).profiles[0].plans[0].end==='2026-11-16'");plan=self.state()['profiles'][0]['plans'][0];self.assertEqual(plan['id'],'historical-kept');self.assertEqual(plan['excludedDates'],['2026-11-23']);self.assertEqual(plan['overrides']['2026-11-18']['start'],'2026-11-19');self.assertEqual(p.locator('#schedule-list article').count(),4)
 def test_nov15_single_location_and_honest_unavailable_distance(self):
  p=self.page;p.goto(base.base.BASE+'/sports/lacrosse/youth');self.assertEqual(p.locator('select[name=location]').count(),1);self.assertEqual(p.locator('select[name=region],select[name=city]').count(),0);allIds=p.locator('[data-record]').evaluate_all('(xs)=>xs.map(x=>x.dataset.record)');self.assertEqual(p.locator('#location').input_value(),'');self.assertEqual(p.locator('#classification').input_value(),'');self.assertEqual(p.locator('#age').input_value(),'');self.assertIn('Distances remain unknown',p.locator('.location-availability').inner_text());p.locator('#location').select_option('south-denver-dtc');p.locator('#classification').select_option('unknown');p.get_by_role('button',name='Search →',exact=True).click();self.assertIn('location=south-denver-dtc',p.url);self.assertIn('classification=unknown',p.url);self.shot('discovery');p.goto(base.base.BASE+'/sports/lacrosse/youth?city=Aurora&region=denver-metro');self.assertEqual(p.locator('#location').input_value(),'legacy');p.locator('#location').select_option('');p.get_by_role('button',name='Search →',exact=True).click();self.assertEqual(p.locator('[data-record]').evaluate_all('(xs)=>xs.map(x=>x.dataset.record)'),allIds);p.goto(base.base.BASE+'/sports/lacrosse/youth?zip=80202');self.assertEqual(p.locator('[data-record]').evaluate_all('(xs)=>xs.map(x=>x.dataset.record)'),allIds)
 def test_nov15_combined_age_location_program_filters_and_manual_club(self):
  p=self.page
  for sport in ['lacrosse','volleyball','basketball','swimming']:
   p.goto(base.base.BASE+'/sports/'+sport+'/youth');p.locator('#location').select_option('denver-metro');p.locator('#classification').select_option('competitive');p.locator('.engine-filter-options summary').click();p.locator('#age').fill('12');p.get_by_role('button',name='Search →',exact=True).click();self.assertEqual(p.locator('#location').input_value(),'denver-metro');self.assertEqual(p.locator('#classification').input_value(),'competitive');self.assertEqual(p.locator('#age').input_value(),'12');expected=p.request.get(base.base.BASE+'/api/data/directory?sport='+sport+'&location=denver-metro&classification=competitive&age=12').json();self.assertEqual(p.locator('.directory-records>[data-record]').evaluate_all('(xs)=>xs.map(x=>x.dataset.record)'),[r['id'] for r in expected])
  p.goto(base.base.BASE+'/build?new=1&guided=1');p.wait_for_selector('#athlete-journey');p.get_by_role('button',name='Add Your Own Club / Team',exact=True).click();club=p.get_by_label('Search club or Add Your Own',exact=True);self.assertIsNone(club.get_attribute('list'));club.fill('Family-only fictional club');self.assertIn('not a verified directory record',p.locator('#athlete-journey').inner_text())
 def test_nov15_family_setup_and_four_pillars_responsive(self):
  p=self.page
  for width,height,name in [(1440,900,'desktop'),(810,1080,'ipad'),(390,844,'iphone')]:
   p.set_viewport_size({'width':width,'height':height});p.goto(base.base.BASE+'/siem/setup');p.wait_for_selector('#siem-participant-add');self.assertEqual(p.locator('.pillar-nav [aria-current=page]').inner_text(),'SIEM');self.assertEqual(p.locator('.pillar-nav a').count(),4);self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'));self.shot('family-setup-'+name)
  p.locator('#siem-participant-add [name=nickname]').fill('Fictional lightweight athlete');p.locator('#siem-participant-add [name=sport]').select_option('swimming');p.get_by_role('button',name='Add lightweight athlete',exact=True).click();self.assertIn('Fictional lightweight athlete',p.locator('#siem-people').inner_text());self.assertIsNone(self.state());p.get_by_role('link',name='Open my family calendar →',exact=True).click();p.wait_for_selector('#platform-calendar');self.assertNotIn('Rivera',p.locator('#platform-calendar').inner_text())
for name in list(vars(base.Consolidated)):
 if name.startswith('test_'):setattr(Nov15,name,None)
if __name__=='__main__':unittest.main(verbosity=2)
